// fayl: proxy.ts
import { geolocation, ipAddress } from "@vercel/functions"
import { NextResponse, type NextRequest } from "next/server"

export function proxy(request: NextRequest) {
  const { country, city } = geolocation(request)
  if (request.nextUrl.pathname === "/" && country === "UZ") {
    return NextResponse.rewrite(new URL("/uz", request.url))
  }
  const res = NextResponse.next()
  const ip = ipAddress(request) ? "ip-bor" : "ip-yo'q"
  res.headers.set("x-visitor", `${country ?? "?"}/${city ?? "?"}/${ip}`)
  return res
}

