import { createClient } from "redis"

const client = createClient({ url: process.env.REDIS_URL })
client.on("error", (err) => console.error("redis:", err.message))
await client.connect()

const tagTimes = new Map() // teg → bekor qilingan vaqt (keyingi misolda umumiy bo'ladi)

const toStream = (bytes) =>
  new ReadableStream({
    start(controller) {
      controller.enqueue(bytes)
      controller.close()
    },
  })

export default {
  async get(cacheKey, softTags) {
    try {
      const raw = await client.get(`uc:${cacheKey}`)
      if (!raw) return undefined
      const e = JSON.parse(raw)
      if (e.tags.some((t) => (tagTimes.get(t) ?? 0) > e.timestamp)) return undefined
      const value = toStream(new Uint8Array(Buffer.from(e.value, "base64")))
      return { ...e, value, expire: e.expire ?? Infinity }
    } catch {
      return undefined // xato = miss, sahifa baribir render bo'ladi
    }
  },

  async set(cacheKey, pendingEntry) {
    try {
      const entry = await pendingEntry
      const bytes = Buffer.from(await new Response(entry.value).arrayBuffer())
      const finite = Number.isFinite(entry.expire)
      const data = { ...entry, value: bytes.toString("base64"), expire: finite ? entry.expire : null }
      await client.set(`uc:${cacheKey}`, JSON.stringify(data), finite ? { EX: Math.max(1, Math.ceil(entry.expire)) } : {})
    } catch (err) {
      console.error("cache set:", err.message)
    }
  },

  async refreshTags() {},
  async getExpiration(tags) {
    return Math.max(0, ...tags.map((t) => tagTimes.get(t) ?? 0))
  },
  async updateTags(tags) {
    for (const t of tags) tagTimes.set(t, Date.now())
  },
}

// fayl: cache-handlers/redis-tags.mjs
import { createClient } from "redis"

const client = createClient({ url: process.env.REDIS_URL })
await client.connect()

export const tagTimes = new Map()

export async function refreshTags() {
  // so'rov boshida: boshqa podlar bekor qilgan teglarni olamiz
  const all = await client.hGetAll("uc:tags")
  for (const [tag, time] of Object.entries(all)) tagTimes.set(tag, Number(time))
}

export async function updateTags(tags, durations) {
  // soddalashtirish: durations (revalidateTag(tag, "max")) bo'lsa ham darhol miss qilamiz
  const now = Date.now()
  for (const tag of tags) {
    tagTimes.set(tag, now)
    await client.hSet("uc:tags", tag, String(now))
  }
}

export async function getExpiration(tags) {
  return Math.max(0, ...tags.map((t) => tagTimes.get(t) ?? 0))
}

