// fayl: adapter/index.mjs
import { writeFile } from "node:fs/promises"
import path from "node:path"

/** @type {import("next").NextAdapter} */
const adapter = {
  name: "oshxona-cdn-manifest",

  modifyConfig(config, { phase }) {
    if (phase !== "phase-production-build") return config
    return { ...config, poweredByHeader: false }
  },

  async onBuildComplete({ outputs, buildId, distDir }) {
    const manifest = {
      buildId,
      pages: outputs.appPages.map((p) => p.pathname),
      routes: outputs.appRoutes.map((r) => r.pathname),
      prerendered: outputs.prerenders.map((p) => p.pathname),
      staticFiles: outputs.staticFiles.length,
    }
    await writeFile(path.join(distDir, "deploy-manifest.json"), JSON.stringify(manifest, null, 2))
    console.log(`adapter: ${manifest.pages.length} sahifa, ${manifest.staticFiles} statik fayl`)
  },
}

